import React, { useEffect, useState } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import StudentPicker from './StudentPicker.jsx';

// Assignment is scoped to one fee-structure line directly (feeStructId <-> studentId), not the
// whole fee group - only the checked students are billed for this specific fee. Students
// already assigned show up checked-and-disabled in the picker (via assignedStudents) so it's
// clear re-checking does nothing; remove one via the View list's own Delete action instead.
const AssignStudentsModal = ({
  isOpen,
  onClose,
  feeStructName,
  assignedStudents = [],
  courseOptions = [],
  candidateStudents = [],
  isCandidatesFetching = false,
  isSaving = false,
  courseFilter,
  searchText,
  onCourseFilterChange,
  onSearchTextChange,
  onSave,
}) => {
  const [selectedMap, setSelectedMap] = useState({});

  useEffect(() => {
    if (isOpen) {
      setSelectedMap({});
    }
  }, [isOpen]);

  const toggleStudent = (student, checked) => {
    setSelectedMap(prev => {
      const next = { ...prev };
      if (checked) {
        next[student.studentId] = { ...prev[student.studentId], ...student };
      } else {
        delete next[student.studentId];
      }
      return next;
    });
  };

  const handleSave = () => onSave(Object.values(selectedMap));

  return (
    <Modal size="lg" isOpen={isOpen}>
      <ModalHeader toggle={onClose}>Assign Students &mdash; {feeStructName}</ModalHeader>
      <ModalBody>
        <div style={{ fontSize: 12, color: '#9a9a9a', marginBottom: 10 }}>
          These students will be charged <b>&quot;{feeStructName}&quot;</b> directly. Names greyed out below are already
          assigned - check a new name to add them; to remove someone already assigned, use Delete in the View list
          instead.
        </div>
        <StudentPicker
          courseOptions={courseOptions}
          candidateStudents={candidateStudents}
          isCandidatesFetching={isCandidatesFetching}
          courseFilter={courseFilter}
          searchText={searchText}
          onCourseFilterChange={onCourseFilterChange}
          onSearchTextChange={onSearchTextChange}
          selectedMap={selectedMap}
          onToggle={toggleStudent}
          onClearAll={() => setSelectedMap({})}
          disabledStudentIds={assignedStudents.map(s => s.studentId)}
        />
      </ModalBody>
      <ModalFooter>
        <CustomButton showLoader loading={isSaving} disabled={isSaving} onClick={handleSave} name="Save" />
        <CustomButton
          className="ml-2"
          type="button"
          color="default"
          disabled={isSaving}
          onClick={onClose}
          name="Cancel"
        />
      </ModalFooter>
    </Modal>
  );
};

export default AssignStudentsModal;
