import React, { useEffect, useState } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Label, FormGroup, Row, Col, Input } from 'reactstrap';
import CustomButton from '../../../../components/CustomButton';
import { coursesStatic, courseStageList } from 'config/constants';
import CustomSelect from 'components/CustomSelect';
import { formResMessage } from 'utils/commonFunc';

export const feeGroupTypes = [
  { label: `For ${coursesStatic}`, value: 'FOR_CLASSES' },
  { label: `For Students`, value: 'FOR_STUDENTS' },
];
// When opened from the Student Fees tab, fixedGroupType is 'FOR_STUDENTS' - that context already
// tells us the group type, so the picker is pointless (and confusing: nothing stopped someone
// from creating a "for classes" group from inside the student-only section). Category still
// defaults to General, but stays editable.
const buildItem = fixedGroupType => ({
  groupType: fixedGroupType || 'FOR_CLASSES',
  groupName: '',
  groupDesc: fixedGroupType ? 'GENERAL' : '',
});
const buildInitialState = fixedGroupType => ({
  item: buildItem(fixedGroupType),
  errors: {},
  loading: false,
});
const FeeGroupFormModal = ({
  isModalOpen,
  formModalCloseProp,
  addFeeGroup,
  feesUpdateSuccess,
  fixedGroupType = null,
}) => {
  const [stateVal, setState] = useState(() => buildInitialState(fixedGroupType));
  const { item, errors, loading } = stateVal;

  // This modal never unmounts (only `isModalOpen` toggles visibility), so re-seed the form fresh
  // every time it opens - otherwise it'd keep whatever state was left over from the very first
  // mount, before fixedGroupType even had its real value.
  useEffect(() => {
    if (isModalOpen) {
      setState(buildInitialState(fixedGroupType));
    }
  }, [isModalOpen]);

  const handleChange = (name, val) => {
    setState(prevState => ({ ...prevState, item: { ...prevState.item, [name]: val } }));
  };

  const validate = () => {
    const newErrors = {};
    if (!item.groupName) newErrors.groupName = 'Group name cannot be empty';
    if (!item.groupType) newErrors.groupType = 'Group type cannot be empty';
    return newErrors;
  };

  const handleSubmit = e => {
    e.preventDefault();
    const newErrors = validate();
    setState(prevState => ({ ...prevState, errors: newErrors }));
    if (!Object.keys(newErrors).length) {
      setState(prevState => ({ ...prevState, loading: true }));
      // The backend takes a list here (this form used to support adding several groups at once);
      // now it's always a single-item list.
      return addFeeGroup([item])
        .then(() => {
          stateReset();
          feesUpdateSuccess('feeGroup');
        })
        .catch(err => setError(err));
    }
  };

  const setError = err => {
    setState(prevState => ({
      ...prevState,
      errors: { global: formResMessage(err) },
      loading: false,
    }));
  };

  const stateReset = () => {
    setState(buildInitialState(fixedGroupType));
  };

  const formModalClose = () => {
    stateReset();
    formModalCloseProp();
  };

  return (
    <Modal size="lg" isOpen={isModalOpen}>
      <form onSubmit={handleSubmit}>
        <ModalHeader>Add Fee Group</ModalHeader>
        <ModalBody>
          {errors?.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
          <Row>
            {!fixedGroupType && (
              <Col sm={4} md={4}>
                <FormGroup>
                  <Label htmlFor="">Group type</Label>
                  <CustomSelect
                    name="groupType"
                    noLabel={true}
                    value={item.groupType}
                    onChange={(name, val) => handleChange('groupType', val)}
                    options={feeGroupTypes}
                    applyLabelStyle={true}
                  />
                  {errors?.groupType && <span className="err-msg">{errors.groupType}</span>}
                </FormGroup>
              </Col>
            )}
            <Col sm={fixedGroupType ? 6 : 4} md={fixedGroupType ? 6 : 4}>
              <FormGroup>
                <Label htmlFor="">
                  Group name <sup> *</sup>
                </Label>
                <Input
                  name="groupName"
                  onChange={e => handleChange('groupName', e.target.value)}
                  value={item.groupName}
                  placeholder="Enter here..."
                  maxLength="50"
                />
                {errors?.groupName && <span className="err-msg">{errors.groupName}</span>}
              </FormGroup>
            </Col>
            <Col sm={fixedGroupType ? 6 : 4} md={fixedGroupType ? 6 : 4}>
              <FormGroup>
                <Label htmlFor="">Category (Optional)</Label>
                <CustomSelect
                  name="groupDesc"
                  noLabel={true}
                  value={item.groupDesc}
                  onChange={(name, val) => handleChange('groupDesc', val)}
                  options={courseStageList}
                  applyLabelStyle={true}
                />
              </FormGroup>
            </Col>
          </Row>
        </ModalBody>
        <ModalFooter>
          <CustomButton type="submit" disabled={loading} name="Save" loading={loading} />
          <CustomButton
            className="ml-2"
            group="button"
            color="default"
            disabled={loading}
            onClick={formModalClose}
            name="Cancel"
          />
        </ModalFooter>
      </form>
    </Modal>
  );
};

export default FeeGroupFormModal;
