import React, { useEffect, useState } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter } from 'reactstrap';
import CustomButton from 'components/CustomButton';
import ClassPicker from './ClassPicker.jsx';
import { coursesStatic } from 'config/constants.js';

const AssignClassesModal = ({
  isOpen,
  onClose,
  feeGroupName,
  assignedClasses = [],
  classOptions = [],
  isSaving = false,
  onSave,
}) => {
  const [selectedMap, setSelectedMap] = useState({});
  const [searchText, setSearchText] = useState('');

  useEffect(() => {
    if (isOpen) {
      const initial = {};
      assignedClasses.forEach(el => {
        initial[el.courseId] = el;
      });
      setSelectedMap(initial);
      setSearchText('');
    }
  }, [isOpen, assignedClasses]);

  const toggleClass = (cls, checked) => {
    setSelectedMap(prev => {
      const next = { ...prev };
      if (checked) {
        next[cls.courseId] = { ...prev[cls.courseId], ...cls };
      } else {
        delete next[cls.courseId];
      }
      return next;
    });
  };

  const handleSave = () => onSave(Object.values(selectedMap));

  return (
    <Modal size="lg" isOpen={isOpen}>
      <ModalHeader toggle={onClose}>
        Assign {coursesStatic} &mdash; {feeGroupName}
      </ModalHeader>
      <ModalBody>
        <div style={{ fontSize: 12, color: '#9a9a9a', marginBottom: 10 }}>
          Every student in a checked {coursesStatic} will be charged every fee under <b>&quot;{feeGroupName}&quot;</b>.
        </div>
        <ClassPicker
          classOptions={classOptions}
          searchText={searchText}
          onSearchTextChange={setSearchText}
          selectedMap={selectedMap}
          onToggle={toggleClass}
          onClearAll={() => setSelectedMap({})}
        />
      </ModalBody>
      <ModalFooter>
        <CustomButton loading={isSaving} disabled={isSaving} onClick={handleSave} name="Save" />
        <CustomButton
          className="ml-2"
          type="button"
          color="default"
          disabled={isSaving}
          onClick={onClose}
          name="Cancel"
        />
      </ModalFooter>
    </Modal>
  );
};

export default AssignClassesModal;
