import React, { useState } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col } from 'reactstrap';
import CustomButton from '../../../../components/CustomButton';
// import AddCircleIcon from '@material-ui/icons/AddCircle';
import RemoveCircleIcon from '@material-ui/icons/RemoveCircle';
import { Paper } from '@material-ui/core';
import CustomInput from 'views/admin/Common/CustomInput';
import { formResMessage } from 'utils/commonFunc';

const itemToAdd = {
  actualAmount: '',
  discountAmount: '',
  discountPercentage: 0,
  expectedAmount: 0,
  feeDescription: '',
  // feeGroupId: 0,
  // feeStructId: 0,
  // schoolId: 0,
};
const stateObj = {
  data: {
    structureListData: [itemToAdd],
  },
  feesStructure: '',
  errors: [],
  loading: false,
};
const FeeStructureFormModal = ({
  feeGroupName,
  isModalOpen,
  formModalCloseProp,
  addFeeStructure,
  feesUpdateSuccess,
}) => {
  const [stateVal, setState] = useState(stateObj);
  const { structureListData } = stateVal?.data || {};

  // const handleSelectChange = (name, selectItem) => {
  //   setState(prevState => ({
  //     ...prevState,
  //     data: {
  //       ...prevState.data,
  //       [name]: selectItem.value,
  //     },
  //   }));
  // };

  const handleChange = (name, val, inx) => {
    let listData = [...structureListData];
    listData[inx] = {
      ...listData?.[inx],
      [name]: val,
    };
    setState(prevState => ({
      ...prevState,
      data: { ...prevState.data, structureListData: listData },
    }));
  };

  const handleSubmit = e => {
    e.preventDefault();
    const errors = validate(structureListData);
    setState(prevState => ({ ...prevState, errors }));
    if (!errors?.filter(el => el)?.length) {
      setState(prevState => ({ ...prevState, loading: true }));
      const postData = structureListData.map(el => {
        const discountAmount = Number(el?.discountAmount) || 0;
        return { ...el, discountAmount, expectedAmount: Number(el?.actualAmount) - discountAmount };
      });
      return addFeeStructure(postData)
        .then(() => {
          stateReset();
          feesUpdateSuccess('feeStructure');
        })
        .catch(err => setError(err));
    }
  };

  const setError = err => {
    setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  const stateReset = () => {
    setState(stateObj);
  };

  const formModalClose = () => {
    stateReset();
    formModalCloseProp();
  };

  const feeNamePattern = /^(?=.*[a-zA-Z])[a-zA-Z0-9 ]+$/;

  const validate = data => {
    const feeDescriptionEmpty = 'Fee name cannot be empty';
    const feeDescriptionInvalid = 'Fee name must contain letters - no pure numbers or special characters';
    const actualAmount = 'Amount cannot be empty';
    const discAmountCantBeMoreThanActual = 'Amount cannot be more than actual amount';
    const errors = data.map(el => {
      const isDisCountAmountIsMore = Number(el?.discountAmount || 0) > Number(el?.actualAmount);
      const trimmedName = el.feeDescription?.trim();
      const isNameInvalid = !!trimmedName && !feeNamePattern.test(trimmedName);
      return !trimmedName || !el.actualAmount || isDisCountAmountIsMore || isNameInvalid
        ? {
            feeDescription: !trimmedName ? feeDescriptionEmpty : isNameInvalid ? feeDescriptionInvalid : null,
            actualAmount: !el.actualAmount ? actualAmount : null,
            discountAmount: isDisCountAmountIsMore ? discAmountCantBeMoreThanActual : null,
          }
        : null;
    });
    return errors;
  };

  const addFeeStructureItem = () => {
    structureListData.push(itemToAdd);
    setState(prevState => ({ ...prevState, data: { structureListData } }));
  };

  const removeFeeStructureItem = inx => {
    structureListData.splice(inx, 1);
    setState(prevState => ({ ...prevState, data: { structureListData } }));
  };

  const { data, errors, loading } = stateVal;
  const thisData = (
    <Modal size="lg" isOpen={isModalOpen}>
      <form onSubmit={handleSubmit}>
        <ModalHeader>{data.feesId ? 'Update Fee Structure' : 'Add Fee Structure'}</ModalHeader>
        <ModalBody>
          {errors?.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
          <div className="content">
            <div className="container-fluid">
              <div className="mt-3 mb-3">
                <b>Group: {feeGroupName}</b>
              </div>
              {structureListData.map((el, inx) => {
                return (
                  <React.Fragment key={inx}>
                    <Row key={inx}>
                      <Col md={11} sm={11} xs={11} lg={11}>
                        <Paper
                          variant="outlined"
                          style={{
                            borderColor: '2 px solid grey',
                            marginBottom: 20,
                            paddingLeft: 10,
                            paddingRight: 10,
                            paddingTop: 5,
                          }}>
                          <Row>
                            <Col sm={12} md={12} xs={12} lg={12}>
                              <CustomInput
                                name="feeDescription"
                                onChange={(name, val) => handleChange(name, val, inx)}
                                value={el.feeDescription}
                                placeholder="Enter here..."
                                error={errors?.[inx]?.feeDescription}
                                label="Fee name"
                              />
                            </Col>
                            <Col sm={4} md={4} xs={4} lg={4}>
                              <CustomInput
                                type="number"
                                name="actualAmount"
                                onChange={(name, val) => handleChange(name, val, inx)}
                                value={el.actualAmount}
                                placeholder="Enter here..."
                                error={errors?.[inx]?.actualAmount}
                                label="Fee amount"
                              />
                            </Col>
                            <Col sm={4} md={4} xs={4} lg={4}>
                              <CustomInput
                                type="number"
                                name="discountAmount"
                                onChange={(name, val) => handleChange(name, val, inx)}
                                value={el.discountAmount}
                                placeholder="Enter here..."
                                error={errors?.[inx]?.discountAmount}
                                label="Discount amount"
                              />
                            </Col>
                            <Col sm={4} md={4} xs={4} lg={4}>
                              <CustomInput
                                type="number"
                                name="expectedAmount"
                                value={el?.actualAmount - el?.discountAmount || ''}
                                placeholder="Enter here..."
                                label="Total fee"
                                disabled
                                onChange={() => {}}
                              />
                            </Col>
                          </Row>
                        </Paper>
                      </Col>
                      {!!inx && (
                        <Col>
                          {/* <CustomButton
                            structure="button"
                            // color="primary"
                            // disabled={loading}
                            onClick={() => removeFeeStructureItem(inx)}
                            name={ */}
                          <RemoveCircleIcon
                            style={{ cursor: 'pointer' }}
                            color="secondary"
                            onClick={() => removeFeeStructureItem(inx)}
                          />
                          {/* }
                            size="small"
                            style={{ marginTop: 30, borerRadius: 15 }}
                          /> */}
                        </Col>
                      )}
                    </Row>
                    {inx + 1 === structureListData.length && structureListData.length < 5 && (
                      <Row>
                        <Col>
                          <CustomButton
                            structure="button"
                            color="primary"
                            // disabled={loading}
                            onClick={addFeeStructureItem}
                            name="Add new"
                            size="small"
                          />
                        </Col>
                      </Row>
                    )}
                  </React.Fragment>
                );
              })}
            </div>
          </div>
        </ModalBody>
        <ModalFooter>
          <CustomButton type="submit" disabled={loading} name="Save" loading={loading} />
          <CustomButton
            className="ml-2"
            structure="button"
            color="default"
            disabled={loading}
            onClick={formModalClose}
            name="Cancel"
          />
        </ModalFooter>
      </form>
    </Modal>
  );
  return <div>{thisData}</div>;
};

export default FeeStructureFormModal;
