import React, { useEffect, useState } from 'react';
import moment from 'moment';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Label, Table } from 'reactstrap';
import Input from '@material-ui/core/TextField';
import Badge from '@material-ui/core/Badge';
import DeleteIcon from '@material-ui/icons/Delete';
import EditIcon from '@material-ui/icons/Edit';
import CustomButton from 'components/CustomButton';
import { CommonLoader } from '../../Common/Loader.jsx';
import { formResMessage, formatMoney } from 'utils/commonFunc';
import { formStudentName } from 'config/constants.js';

// The backend's FeeType enum only ever has DISCOUNT_FEE - this modal is Concession-only.
// Arrears/fines aren't adjust-student-fee records at all; they're added as a regular
// fee-structure line assigned to just the students who owe it (see the Student Fees tab).
const typeLabel = feeType => (feeType === 'REFUND_FEE' ? 'Refund' : 'Concession');

const emptyForm = { adjustFeeId: 0, feeType: null, amount: '', feeDesc: '' };

const StudentFeeAdjustmentModal = ({
  isOpen,
  onClose,
  student,
  adjustments = [],
  isFetching = false,
  isSaving = false,
  onCreate,
  onUpdate,
  onDelete,
  showWarning,
}) => {
  const [form, setForm] = useState(emptyForm);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    if (isOpen) {
      setForm(emptyForm);
      setErrors({});
    }
  }, [isOpen, student?.studentId]);

  const handleChange = (name, value) => setForm(prev => ({ ...prev, [name]: value }));

  const startAdd = feeType => setForm({ ...emptyForm, feeType });

  const validate = () => {
    const err = {};
    if (!form.amount || Number(form.amount) <= 0) err.amount = 'Enter a valid amount';
    setErrors(err);
    return !Object.keys(err).length;
  };

  const resetForm = () => setForm(emptyForm);

  const handleSubmit = e => {
    e.preventDefault();
    if (!validate()) return;
    const postData = { feeType: form.feeType, amount: Number(form.amount), feeDesc: form.feeDesc };
    const promise = form.adjustFeeId ? onUpdate(form.adjustFeeId, postData) : onCreate(student?.studentId, postData);
    promise.then(() => resetForm()).catch(err => showWarning?.(formResMessage(err), 'error'));
  };

  const handleEdit = item => {
    setForm({
      adjustFeeId: item.adjustFeeId,
      feeType: item.feeType,
      amount: item.amount,
      feeDesc: item.feeDesc || '',
    });
  };

  // onDelete opens the shared confirm dialog (FeesPage.deleteItem) rather than deleting directly -
  // the actual delete, refetch, and any error toast happen there once the admin confirms.
  const handleDelete = adjustFeeId => onDelete(adjustFeeId);

  return (
    <Modal size="md" isOpen={isOpen}>
      <ModalHeader toggle={onClose}>Concession / Arrear {student ? `- ${formStudentName(student)}` : ''}</ModalHeader>
      <ModalBody>
        {form.feeType ? (
          <form onSubmit={handleSubmit}>
            <div style={{ fontWeight: 'bold', marginBottom: 5 }}>
              {form.adjustFeeId ? 'Update' : 'Add'} {typeLabel(form.feeType)}
            </div>
            <Row>
              <Col md={6} sm={6} xs={6}>
                <Input
                  size="small"
                  type="number"
                  fullWidth
                  margin="normal"
                  variant="outlined"
                  label="Amount"
                  value={form.amount}
                  onChange={e => handleChange('amount', e.target.value)}
                  error={!!errors.amount}
                  helperText={errors.amount}
                />
              </Col>
              <Col md={6} sm={6} xs={6}>
                <Input
                  size="small"
                  fullWidth
                  margin="normal"
                  variant="outlined"
                  label="Description (optional)"
                  placeholder="e.g. SC/ST concession, merit scholarship"
                  value={form.feeDesc}
                  onChange={e => handleChange('feeDesc', e.target.value)}
                />
              </Col>
            </Row>
            <div style={{ textAlign: 'right', marginBottom: 10 }}>
              <CustomButton
                className="mr-2"
                type="button"
                color="default"
                size="small"
                name="Cancel"
                onClick={resetForm}
              />
              <CustomButton
                type="submit"
                size="small"
                loading={isSaving}
                disabled={isSaving}
                name={form.adjustFeeId ? 'Update' : 'Add'}
              />
            </div>
          </form>
        ) : (
          <div style={{ textAlign: 'right', marginBottom: 10 }}>
            <CustomButton
              type="button"
              size="small"
              color="primary"
              name="+ Add Concession"
              onClick={() => startAdd('DISCOUNT_FEE')}
            />
          </div>
        )}
        <Label style={{ fontWeight: 'bold', color: '#9a9a9a', fontSize: 13 }}>Existing Adjustments</Label>
        {isFetching ? (
          <CommonLoader />
        ) : adjustments?.length ? (
          <Table size="sm">
            <thead>
              <tr>
                <th>Type</th>
                <th>Amount</th>
                <th>Description</th>
                <th>Created</th>
                <th className="text-right">Action</th>
              </tr>
            </thead>
            <tbody>
              {adjustments.map(item => (
                <tr key={item.adjustFeeId}>
                  <td>{typeLabel(item.feeType)}</td>
                  <td>{formatMoney(item.amount)}</td>
                  <td>{item.feeDesc || '--'}</td>
                  <td>{item.createdDate ? moment(item.createdDate).format('DD MMM, YYYY hh:mm A') : '--'}</td>
                  <td className="text-right">
                    {item.feeType === 'REFUND_FEE' ? (
                      <span style={{ fontSize: 11, color: '#9a9a9a' }}>Manage from payment row</span>
                    ) : (
                      <>
                        <EditIcon
                          fontSize="small"
                          style={{ cursor: 'pointer', marginRight: 10 }}
                          onClick={() => handleEdit(item)}
                        />
                        <Badge
                          color="danger"
                          style={{ cursor: 'pointer', paddingBlock: 6, paddingInline: 6 }}
                          onClick={() => handleDelete(item.adjustFeeId)}>
                          <DeleteIcon fontSize="small" />
                        </Badge>
                      </>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </Table>
        ) : (
          <div style={{ textAlign: 'center', padding: 10, fontSize: 12, color: '#6b778a' }}>
            No concession, arrear, or refund added for this student yet.
          </div>
        )}
      </ModalBody>
      <ModalFooter>
        <CustomButton type="button" color="default" onClick={onClose} name="Close" />
      </ModalFooter>
    </Modal>
  );
};

export default StudentFeeAdjustmentModal;
