import React, { useEffect, useState } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col } from 'reactstrap';
import Input from '@material-ui/core/TextField';
import CustomButton from 'components/CustomButton';
import StudentPicker from './StudentPicker.jsx';
import { formResMessage } from 'utils/commonFunc';

// One modal reused for both Concession and Arrear - the parent decides the type (and the
// wording) by passing feeType/title/descPlaceholder, so the user is never asked to pick a
// "type" themselves; the button they clicked already said which one this is.
const BulkFeeAdjustmentModal = ({
  isOpen,
  onClose,
  title,
  descPlaceholder,
  feeType,
  // When set, this create is "add more students to an existing concession/arrear" - the
  // description/amount are locked to whatever that group already uses, so the new rows keep
  // matching it exactly (grouping in the list view is just a text match, so this avoids
  // accidentally splitting one concession into two over a typo).
  presetFeeDesc = '',
  presetAmount = '',
  // Students already in this concession/arrear group (only meaningful when locked) - shown
  // checked-and-disabled in the picker so re-checking is a no-op; remove one from the group's
  // View table instead.
  existingStudentIds = [],
  courseOptions = [],
  candidateStudents = [],
  isCandidatesFetching = false,
  courseFilter,
  searchText,
  onCourseFilterChange,
  onSearchTextChange,
  onCreateForStudents,
  showWarning,
}) => {
  const isLocked = !!presetFeeDesc;
  const [feeDesc, setFeeDesc] = useState('');
  const [amount, setAmount] = useState('');
  const [errors, setErrors] = useState({});
  const [selectedMap, setSelectedMap] = useState({});
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    if (isOpen) {
      setFeeDesc(presetFeeDesc || '');
      setAmount(presetAmount || '');
      setErrors({});
      setSelectedMap({});
      setIsSaving(false);
    }
  }, [isOpen]);

  const toggleStudent = (student, checked) => {
    setSelectedMap(prev => {
      const next = { ...prev };
      if (checked) {
        next[student.studentId] = student;
      } else {
        delete next[student.studentId];
      }
      return next;
    });
  };

  const selectedCount = Object.keys(selectedMap).length;

  const validate = () => {
    const err = {};
    if (!feeDesc.trim()) err.feeDesc = 'Enter a name/description';
    if (!amount || Number(amount) <= 0) err.amount = 'Enter a valid amount';
    if (!selectedCount) err.students = 'Select at least one student';
    setErrors(err);
    return !Object.keys(err).length;
  };

  const handleSave = () => {
    if (!validate()) return;
    setIsSaving(true);
    const postData = { feeType, feeDesc, amount: Number(amount) };
    onCreateForStudents(Object.values(selectedMap), postData)
      .then(() => {
        setIsSaving(false);
        onClose();
      })
      .catch(err => {
        setIsSaving(false);
        showWarning?.(formResMessage(err), 'error');
      });
  };

  return (
    <Modal size="lg" isOpen={isOpen}>
      <ModalHeader toggle={onClose}>{isLocked ? `Assign Students — ${presetFeeDesc}` : title}</ModalHeader>
      <ModalBody>
        <Row>
          <Col md={6} sm={6} xs={12}>
            <Input
              size="small"
              fullWidth
              margin="normal"
              variant="outlined"
              label="Name / Description"
              placeholder={descPlaceholder}
              value={feeDesc}
              onChange={e => setFeeDesc(e.target.value)}
              disabled={isLocked}
              error={!!errors.feeDesc}
              helperText={errors.feeDesc}
            />
          </Col>
          <Col md={6} sm={6} xs={12}>
            <Input
              size="small"
              type="number"
              fullWidth
              margin="normal"
              variant="outlined"
              label="Amount"
              value={amount}
              onChange={e => setAmount(e.target.value)}
              disabled={isLocked}
              error={!!errors.amount}
              helperText={errors.amount}
            />
          </Col>
        </Row>
        <div style={{ marginTop: 5 }}>
          <StudentPicker
            courseOptions={courseOptions}
            candidateStudents={candidateStudents}
            isCandidatesFetching={isCandidatesFetching}
            courseFilter={courseFilter}
            searchText={searchText}
            onCourseFilterChange={onCourseFilterChange}
            onSearchTextChange={onSearchTextChange}
            selectedMap={selectedMap}
            onToggle={toggleStudent}
            onClearAll={() => setSelectedMap({})}
            disabledStudentIds={existingStudentIds}
          />
          {errors.students && <div className="err-msg mt-1">{errors.students}</div>}
        </div>
      </ModalBody>
      <ModalFooter>
        <CustomButton
          loading={isSaving}
          disabled={isSaving}
          onClick={handleSave}
          name={isLocked ? 'Assign' : 'Create'}
        />
        <CustomButton
          className="ml-2"
          type="button"
          color="default"
          disabled={isSaving}
          onClick={onClose}
          name="Cancel"
        />
      </ModalFooter>
    </Modal>
  );
};

export default BulkFeeAdjustmentModal;
