import React, { useEffect, useState } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col } from 'reactstrap';
import CustomButton from '../../../../components/CustomButton';
import CustomInput from 'views/admin/Common/CustomInput';
import RemoveCircleIcon from '@material-ui/icons/RemoveCircle';
import { Paper } from '@material-ui/core';
import { formResMessage } from 'utils/commonFunc';
import { normalizeName } from 'actions/admin/transportFee';

const MAX_ROWS = 10;
const emptyRow = { areaName: '', distance: '', amount: '' };
const buildInitialState = () => ({ rows: [{ ...emptyRow }], errors: [], loading: false });

// One row = one stop (TransportArea). The backend still requires a `ruteName` per row, but every
// stop under a group is really just that group's own route - a stop-level route name that differs
// from the group's is exactly what caused stops to silently end up priced under the wrong route
// (see the Thambaram/Poonnamalli mixup). So it's no longer a field here at all: every row is
// submitted with ruteName = groupName behind the scenes, never shown or editable.
//
// editingArea (optional): when set, the modal edits that one existing stop instead of adding new
// ones - single row, pre-filled, no "add another"/remove controls, submits via onUpdate (PUT).
const TransportAreaFormModal = ({
  groupName,
  isModalOpen,
  formModalCloseProp,
  addTransportArea,
  onSuccess,
  editingArea = null,
  onUpdate,
  existingAreaNames = [],
  otherRouteAreas = [],
}) => {
  const [stateVal, setState] = useState(buildInitialState);
  const { rows, errors, loading } = stateVal;
  const isEditing = !!editingArea;

  useEffect(() => {
    if (isModalOpen) {
      setState(
        isEditing
          ? {
              rows: [
                {
                  areaName: editingArea.areaName || '',
                  distance: editingArea.distance ?? '',
                  amount: editingArea.amount ?? '',
                },
              ],
              errors: [],
              loading: false,
            }
          : buildInitialState()
      );
    }
  }, [isModalOpen, editingArea]);

  const handleChange = (name, val, inx) => {
    const nextRows = [...rows];
    nextRows[inx] = { ...nextRows[inx], [name]: val };
    setState(prevState => ({ ...prevState, rows: nextRows }));
  };

  const addRow = () => {
    setState(prevState => ({ ...prevState, rows: [...prevState.rows, { ...emptyRow }] }));
  };

  const removeRow = inx => {
    setState(prevState => ({ ...prevState, rows: prevState.rows.filter((_, i) => i !== inx) }));
  };

  // Distance is optional - an admin may not know the exact distance for a stop, in which case it's
  // left blank (stored/shown as N/A) and the fee is just entered directly via `amount`, which is
  // mandatory since that's the only source of the fee now.
  // Destinations already on this route (minus the one being edited), on the other routes (`otherRouteAreas`:
  // { areaName, routeName }) and repeats within this form are rejected here for instant feedback; the save
  // re-checks every route against the live data.
  const takenNames = (existingAreaNames || [])
    .filter(name => !(isEditing && name === editingArea.areaName))
    .map(normalizeName);

  const duplicateMessage = (row, inx) => {
    const name = normalizeName(row.areaName);
    if (!name) return null;
    if (takenNames.includes(name)) return `"${row.areaName.trim()}" is already a destination on this route`;
    const elsewhere = otherRouteAreas.find(area => normalizeName(area.areaName) === name);
    if (elsewhere) {
      return `"${row.areaName.trim()}" is already a destination on the route "${elsewhere.routeName}"`;
    }
    if (rows.some((other, i) => i !== inx && normalizeName(other.areaName) === name)) {
      return `"${row.areaName.trim()}" is entered more than once`;
    }
    return null;
  };

  const validate = () =>
    rows.map((row, inx) => {
      const distanceInvalid = row.distance !== '' && Number(row.distance) <= 0;
      const amountInvalid = !row.amount || Number(row.amount) <= 0;
      const duplicate = duplicateMessage(row, inx);
      return !row.areaName?.trim() || duplicate || distanceInvalid || amountInvalid
        ? {
            areaName: !row.areaName?.trim() ? 'Destination cannot be empty' : duplicate,
            distance: distanceInvalid ? 'Distance must be a positive number' : null,
            amount: amountInvalid ? 'Amount must be a positive number' : null,
          }
        : null;
    });

  const handleSubmit = e => {
    e.preventDefault();
    const newErrors = validate();
    setState(prevState => ({ ...prevState, errors: newErrors }));
    if (!newErrors.filter(el => el).length) {
      setState(prevState => ({ ...prevState, loading: true }));
      const postRows = rows.map(row => ({
        ...row,
        ruteName: groupName,
        distance: row.distance === '' ? null : Number(row.distance),
        amount: Number(row.amount),
      }));
      const promise = isEditing ? onUpdate(editingArea.transportAreaId, postRows[0]) : addTransportArea(postRows);
      return promise
        .then(() => {
          setState(buildInitialState());
          onSuccess();
        })
        .catch(err =>
          setState(prevState => ({ ...prevState, loading: false, errors: { global: formResMessage(err) } }))
        );
    }
  };

  const formModalClose = () => {
    setState(buildInitialState());
    formModalCloseProp();
  };

  return (
    <Modal size="lg" isOpen={isModalOpen}>
      <form onSubmit={handleSubmit}>
        <ModalHeader>{isEditing ? 'Edit Destination' : 'Add Destination'}</ModalHeader>
        <ModalBody>
          {errors?.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
          <div className="mb-3">
            <b>Group: {groupName}</b>
            {!!existingAreaNames.length && (
              <div style={{ fontSize: 12, color: '#7d7d7d', marginTop: 4 }}>
                Already on this route: {existingAreaNames.join(', ')}
              </div>
            )}
          </div>
          {rows.map((row, inx) => (
            <React.Fragment key={inx}>
              <Row>
                <Col md={11} sm={11} xs={11} lg={11}>
                  <Paper
                    variant="outlined"
                    style={{ marginBottom: 20, paddingLeft: 10, paddingRight: 10, paddingTop: 5 }}>
                    <Row>
                      <Col sm={4} md={4} xs={4} lg={4}>
                        <CustomInput
                          name="areaName"
                          label="Destination *"
                          placeholder="e.g. Guindy"
                          value={row.areaName}
                          onChange={(name, val) => handleChange(name, val, inx)}
                          error={errors?.[inx]?.areaName}
                        />
                      </Col>
                      <Col sm={4} md={4} xs={4} lg={4}>
                        <CustomInput
                          name="distance"
                          type="number"
                          label="Distance from school (km)"
                          placeholder="N/A"
                          value={row.distance}
                          onChange={(name, val) => handleChange(name, val, inx)}
                          error={errors?.[inx]?.distance}
                        />
                      </Col>
                      <Col sm={4} md={4} xs={4} lg={4}>
                        <CustomInput
                          name="amount"
                          type="number"
                          label="Amount *"
                          placeholder="e.g. 1000"
                          value={row.amount}
                          onChange={(name, val) => handleChange(name, val, inx)}
                          error={errors?.[inx]?.amount}
                        />
                      </Col>
                    </Row>
                  </Paper>
                </Col>
                {!isEditing && !!inx && (
                  <Col>
                    <RemoveCircleIcon style={{ cursor: 'pointer' }} color="secondary" onClick={() => removeRow(inx)} />
                  </Col>
                )}
              </Row>
              {!isEditing && inx + 1 === rows.length && rows.length < MAX_ROWS && (
                <Row>
                  <Col>
                    <CustomButton
                      type="button"
                      color="primary"
                      onClick={addRow}
                      name="Add new destination"
                      size="small"
                    />
                  </Col>
                </Row>
              )}
            </React.Fragment>
          ))}
        </ModalBody>
        <ModalFooter>
          <CustomButton type="submit" disabled={loading} name="Save" loading={loading} />
          <CustomButton
            className="ml-2"
            type="button"
            color="default"
            disabled={loading}
            onClick={formModalClose}
            name="Cancel"
          />
        </ModalFooter>
      </form>
    </Modal>
  );
};

export default TransportAreaFormModal;
