import React from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter } from 'reactstrap';
import Table from '@material-ui/core/Table';
import TableBody from '@material-ui/core/TableBody';
import TableCell from '@material-ui/core/TableCell';
import TableHead from '@material-ui/core/TableHead';
import TableRow from '@material-ui/core/TableRow';
import CustomButton from 'components/CustomButton';
import { formStudentName, regNoStatic } from 'config/constants.js';
import { formRegNoWithUsername } from 'utils/commonFunc.js';
import { CommonLoader } from '../../Common/Loader.jsx';
import EmptyState from 'views/admin/Common/EmptyState';

// View of who's directly assigned to one fee-structure line, opened from the row's "View"
// action. Identification info (name, reg no, email, class) plus a per-student Delete, since
// this list is clubbed the same way as Concession/Arrear's grouped view - no concession/arrear
// link here though, that's a separate, unrelated concern.
//
// assignedStudents can render before the name/email/reg-no enrichment lookup for those rows has
// resolved (that lookup runs separately from the list itself) - isFetching lets the caller show
// a loader for that window instead of rows with blank/undefined fields.
const ViewAssignedStudentsModal = ({
  isOpen,
  onClose,
  feeStructName,
  assignedStudents = [],
  isFetching = false,
  onDelete,
}) => {
  const style = { color: '#7d7d7d', fontSize: 12 };
  return (
    <Modal size="lg" isOpen={isOpen} toggle={onClose}>
      <ModalHeader toggle={onClose}>
        Students Assigned &mdash; {feeStructName} ({assignedStudents.length})
      </ModalHeader>
      <ModalBody>
        {isFetching ? (
          <div style={{ textAlign: 'center', padding: 20 }}>
            <CommonLoader />
          </div>
        ) : assignedStudents.length ? (
          <div style={{ overflowX: 'auto' }}>
            <Table size="small" aria-label="a dense table">
              <TableHead>
                <TableRow>
                  <TableCell component="th" style={style}>
                    <b>Name</b>
                  </TableCell>
                  <TableCell component="th" style={style}>
                    <b>{regNoStatic}</b>
                  </TableCell>
                  <TableCell component="th" style={style}>
                    <b>Class</b>
                  </TableCell>
                  <TableCell component="th" align="right" style={style}>
                    <b>Action</b>
                  </TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {assignedStudents.map(student => (
                  <TableRow key={student.studentId}>
                    <TableCell>{formStudentName(student)}</TableCell>
                    <TableCell>{formRegNoWithUsername(student.registerNumber, student.email)}</TableCell>
                    <TableCell>{student.courseName || '--'}</TableCell>
                    <TableCell align="right">
                      <CustomButton
                        variant="outlined"
                        color="default"
                        size="small"
                        style={{ float: 'right', color: '#c62828', borderColor: '#c62828' }}
                        onClick={() => onDelete(student.studFeeStrId)}
                        name="Delete"
                      />
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </div>
        ) : (
          <EmptyState compact bare icon="fas fa-user-graduate" title="No students assigned yet" />
        )}
      </ModalBody>
      <ModalFooter>
        <CustomButton type="button" color="default" onClick={onClose} name="Close" />
      </ModalFooter>
    </Modal>
  );
};

export default ViewAssignedStudentsModal;
