import React, { useEffect, useState } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Label, FormGroup, Row, Col, Input } from 'reactstrap';
import Checkbox from '@material-ui/core/Checkbox';
import FormControlLabel from '@material-ui/core/FormControlLabel';
import CustomButton from '../../../../components/CustomButton';
import { formResMessage } from 'utils/commonFunc';
import { findSimilarNames, normalizeName } from 'actions/admin/transportFee';
import NoteBox from 'views/admin/Common/NoteBox';

const buildInitialState = () => ({
  description: '',
  errors: {},
  confirmedSimilar: false,
  loading: false,
});

// Group here is a TransportFeeStructure row - calculationType is always DISTANCE_BASED (the
// only mode this UI supports), so it's never shown as a field. Each stop under the group carries
// its own fee amount directly (see TransportAreaFormModal), rather than one computed from a
// shared slab table.
//
// `existingRoutes` ({ transportFeeStructId, description }) are the routes already added. A name that is
// already taken is refused. A name that merely contains, or is contained in, an existing one ("Chennai" vs
// "Chennai route") is allowed only after the user ticks that it is a different route.
const TransportGroupFormModal = ({
  isModalOpen,
  formModalCloseProp,
  addTransportGroup,
  onSuccess,
  existingRoutes = [],
  note,
}) => {
  const [stateVal, setState] = useState(buildInitialState);
  const { description, errors, confirmedSimilar, loading } = stateVal;
  const similarRoutes = findSimilarNames(description, existingRoutes, route => route.description);

  useEffect(() => {
    if (isModalOpen) {
      setState(buildInitialState());
    }
  }, [isModalOpen]);

  const handleSubmit = e => {
    e.preventDefault();
    if (loading) return;
    if (!description.trim()) {
      setState(prevState => ({ ...prevState, errors: { description: 'Route name cannot be empty' } }));
      return;
    }
    // Instant feedback from the routes already on screen; the save re-checks against the live list.
    const clash = existingRoutes.find(route => normalizeName(route.description) === normalizeName(description));
    if (clash) {
      setState(prevState => ({
        ...prevState,
        errors: { description: `"${clash.description}" already exists. Use that route instead of adding it again.` },
      }));
      return;
    }
    if (similarRoutes.length && !confirmedSimilar) {
      setState(prevState => ({
        ...prevState,
        errors: { similar: 'Tick the box to confirm this is a different route.' },
      }));
      return;
    }
    setState(prevState => ({ ...prevState, loading: true, errors: {} }));
    return addTransportGroup({ description: description.trim(), calculationType: 'DISTANCE_BASED' })
      .then(() => {
        setState(buildInitialState());
        onSuccess();
      })
      .catch(err =>
        setState(prevState => ({
          ...prevState,
          loading: false,
          errors: { global: formResMessage(err) },
        }))
      );
  };

  const formModalClose = () => {
    setState(buildInitialState());
    formModalCloseProp();
  };

  return (
    <Modal size="md" isOpen={isModalOpen}>
      <form onSubmit={handleSubmit}>
        <ModalHeader>Add Route</ModalHeader>
        <ModalBody>
          {!!note && <div style={{ marginBottom: 12 }}>{note}</div>}
          {errors?.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
          <Row>
            <Col sm={12} md={12}>
              <FormGroup>
                <Label htmlFor="">
                  Route name <sup> *</sup>
                </Label>
                <Input
                  name="description"
                  onChange={e =>
                    setState(prevState => ({
                      ...prevState,
                      description: e.target.value,
                      confirmedSimilar: false,
                      errors: {},
                    }))
                  }
                  value={description}
                  placeholder="e.g. Chennai Routes"
                  maxLength="80"
                />
                {errors?.description && <span className="err-msg">{errors.description}</span>}
                {!!similarRoutes.length && (
                  <div style={{ marginTop: 10 }}>
                    <NoteBox label="Similar route already exists:">
                      {similarRoutes.map(route => `"${route.description}"`).join(', ')}. Add yours only if it is a
                      different route.
                    </NoteBox>
                    <FormControlLabel
                      style={{ marginBottom: 0 }}
                      control={
                        <Checkbox
                          size="small"
                          checked={confirmedSimilar}
                          onChange={e =>
                            setState(prevState => ({
                              ...prevState,
                              confirmedSimilar: e.target.checked,
                              errors: {},
                            }))
                          }
                        />
                      }
                      label={<span style={{ fontSize: 13 }}>Yes, this is a different route</span>}
                    />
                    {errors?.similar && <div className="err-msg">{errors.similar}</div>}
                  </div>
                )}
              </FormGroup>
            </Col>
          </Row>
        </ModalBody>
        <ModalFooter>
          <CustomButton type="submit" disabled={loading} name="Save" loading={loading} />
          <CustomButton
            className="ml-2"
            type="button"
            color="default"
            disabled={loading}
            onClick={formModalClose}
            name="Cancel"
          />
        </ModalFooter>
      </form>
    </Modal>
  );
};

export default TransportGroupFormModal;
