import React from 'react';
import moment from 'moment';
import { Modal, ModalHeader, ModalBody, ModalFooter } from 'reactstrap';
import Table from '@material-ui/core/Table';
import TableBody from '@material-ui/core/TableBody';
import TableCell from '@material-ui/core/TableCell';
import TableHead from '@material-ui/core/TableHead';
import TableRow from '@material-ui/core/TableRow';
import IconButton from '@material-ui/core/IconButton';
import DeleteIcon from '@material-ui/icons/Delete';
import CustomButton from 'components/CustomButton';
import { formStudentName, regNoStatic } from 'config/constants.js';
import { formRegNoWithUsername } from 'utils/commonFunc.js';

// One concession/arrear "group" - every row in the flat AdjustStudentFee list that shares the
// same description/type/amount, shown together since that's exactly how they were created
// (Create Concession/Arrear already assigns one description+amount to many students at once).
const ViewAdjustGroupModal = ({ isOpen, onClose, feeDesc, students = [], onAssignMore, onDelete }) => {
  const style = { color: '#7d7d7d', fontSize: 12 };
  return (
    <Modal size="lg" isOpen={isOpen} toggle={onClose}>
      <ModalHeader toggle={onClose}>
        {feeDesc} ({students.length})
      </ModalHeader>
      <ModalBody>
        <div style={{ textAlign: 'right', marginBottom: 10 }}>
          <CustomButton onClick={onAssignMore} name="+ Assign more students" />
        </div>
        {students.length ? (
          <Table size="small" aria-label="a dense table">
            <TableHead>
              <TableRow>
                <TableCell component="th" style={style}>
                  <b>Name</b>
                </TableCell>
                <TableCell component="th" style={style}>
                  <b>{regNoStatic}</b>
                </TableCell>
                <TableCell component="th" style={style}>
                  <b>Class</b>
                </TableCell>
                <TableCell component="th" style={style}>
                  <b>Created</b>
                </TableCell>
                <TableCell component="th" align="right" style={style}>
                  <b>Action</b>
                </TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {students.map(item => (
                <TableRow key={item.adjustFeeId}>
                  <TableCell>{formStudentName(item)}</TableCell>
                  <TableCell>{formRegNoWithUsername(item.registerNumber, item.email)}</TableCell>
                  <TableCell>{item.courseName || '--'}</TableCell>
                  <TableCell>
                    {item.createdDate ? moment(item.createdDate).format('DD MMM, YYYY hh:mm A') : '--'}
                  </TableCell>
                  <TableCell align="right">
                    <IconButton
                      size="small"
                      style={{ float: 'right', border: '1px solid #c62828', borderRadius: 4, padding: 6 }}
                      onClick={() => onDelete(item.adjustFeeId)}>
                      <DeleteIcon style={{ fontSize: 14, color: '#c62828' }} />
                    </IconButton>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        ) : (
          <div style={{ fontSize: 12, color: '#9a9a9a' }}>No students left in this group.</div>
        )}
      </ModalBody>
      <ModalFooter>
        <CustomButton type="button" color="default" onClick={onClose} name="Close" />
      </ModalFooter>
    </Modal>
  );
};

export default ViewAdjustGroupModal;
