import React from 'react';

// A highlighted note (soft orange box, orange accent bar) for information that is easy to miss as plain
// grey text. Orange isn't in config/colors, but the Transport screens already use it for warnings, and it
// stands out against the purple theme.
const NoteBox = ({ label = 'Note:', children }) => (
  <div
    style={{
      background: '#FFF3E0',
      border: '1px solid #FFCC80',
      borderLeft: '4px solid #F57C00',
      borderRadius: 4,
      padding: '8px 12px',
      fontSize: 12.5,
      lineHeight: 1.4,
      color: '#6D3300',
    }}>
    <b style={{ color: '#E65100' }}>{label} </b>
    {children}
  </div>
);

export default NoteBox;
